def far(ws):
    m = sorted(ws)[len(ws) // 2]
    out = []
    for w in ws:
        if abs(w - m) > m / 2:
            out.append(w)
    return out

print(far([210, 195, 40, 205]))
print(far([38, 42, 190]))

def redact(text):
    out = ""
    for c in text:
        if c.isdigit():
            out += "#"
        else:
            out += c
    return out

print(redact("Call 0803 555 1234 after 4pm"))

