steps.solution:
def label(score):
    if score >= 0.5:
        return "sick"
    return "healthy"

def fragile(score, eps):
    a = label(score - eps)
    b = label(score + eps)
    return a != b

print(fragile(0.52, 0.05))
print(fragile(0.90, 0.05))

